"""Hepburn romaji from kana. Generated by code, never by the LLM."""

import threading

_lock = threading.Lock()
_converter = None


def _get_converter():
    global _converter
    if _converter is None:
        with _lock:
            if _converter is None:
                import pykakasi

                _converter = pykakasi.kakasi()
    return _converter


def kana_to_romaji(kana: str) -> str:
    """Transliterate pure kana (e.g. a verified word reading)."""
    segments = _get_converter().convert(kana)
    return "".join(seg["hepburn"] for seg in segments).strip()
